"""Stage transparent smoke and underbody glow; leave decoded metadata unchanged."""
import hashlib
import io
import json
import struct
from PIL import Image
from inspect_assets import ROOT,chunks,flatten,jdlz
from extract_assets import dds_header,mip_layout
from prepare_tiremask import rewrite_jdlz


def prepare(source,names):
    output=bytearray(source);ranges=[]
    for root in flatten(chunks(source)):
        if root['id']!='0xb3300000':continue
        nodes=list(flatten(root['children']))
        infos=[n for n in nodes if n['id']=='0x33310004'];data=[n for n in nodes if n['id']=='0x33320002']
        if len(infos)!=1 or len(data)!=1:continue
        info,pixels=infos[0],data[0]
        if info['size']%124:raise ValueError('Partial TextureInfo')
        for at in range(info['payload'],info['end'],124):
            name=source[at+12:at+36].split(b'\0')[0].decode('ascii',errors='replace')
            if name not in names:continue
            placement=struct.unpack_from('<I',source,at+48)[0];size=struct.unpack_from('<I',source,at+56)[0]
            width,height=struct.unpack_from('<HH',source,at+68);fmt=source[at+74];mips=source[at+78]
            if fmt!=0x24 or not 1<=width<=1024 or not 1<=height<=1024:raise ValueError('Unexpected effect texture format')
            levels=mip_layout(width,height,fmt,size)
            if len(levels)!=mips:raise ValueError('Mip count mismatch')
            begin=pixels['payload']+120+placement;end=begin+size
            if begin%128 or begin<pixels['payload']+120 or end>pixels['end']:raise ValueError('Texture outside aligned pixel block')
            output[begin:end]=bytes(size)
            for level in levels:
                offset=begin+level['offset'];length=level['bytes']
                image=Image.open(io.BytesIO(dds_header(level['width'],level['height'],b'DXT3',length)+output[offset:offset+length])).convert('RGBA')
                if image.getextrema()!=((0,0),)*4:raise ValueError('Effect mip not transparent black')
            ranges.append({'name':name,'offset':begin,'bytes':size,'width':width,'height':height,'mips':mips})
    if sorted(r['name'] for r in ranges)!=sorted(names):raise ValueError('Effect absent or ambiguous')
    cursor=0
    for row in sorted(ranges,key=lambda r:r['offset']):
        begin=row['offset'];end=begin+row['bytes']
        if begin<cursor or source[cursor:begin]!=output[cursor:begin]:raise ValueError('Unrelated bytes changed or ranges overlap')
        cursor=end
    if source[cursor:]!=output[cursor:] or chunks(source)!=chunks(output):raise ValueError('Unrelated data or layout changed')
    return bytes(output),ranges


def main():
    files=[];sha=lambda data:hashlib.sha256(data).hexdigest()
    for stem,names in [('InGameCommon',{'SFX_SMOKE_A_CS','SFX_SMOKE_B_CS'}),('GLOBALB',{'NEONBLUR'})]:
        raw=ROOT/'GLOBAL'/f'{stem}.bun';raw=raw if raw.exists() else ROOT/'GLOBAL'/f'{stem}.BUN'
        packed=ROOT/'GLOBAL'/('GlobalB.lzc' if stem=='GLOBALB' else stem+'.lzc')
        source=raw.read_bytes();encoded=packed.read_bytes()
        if jdlz(encoded)!=source:raise ValueError('Raw/compressed baseline mismatch')
        candidate,ranges=prepare(source,names);compressed=rewrite_jdlz(encoded,candidate)
        for target,before,after in [(raw,source,candidate),(packed,encoded,compressed)]:
            relative=target.relative_to(ROOT);out=ROOT/'modding/staged-runtime/smoke-neon'/relative;out.parent.mkdir(parents=True,exist_ok=True);out.write_bytes(after)
            files.append({'target':str(relative),'candidate':str(out.relative_to(ROOT)),'backup':str(relative)+'.before-smoke-neon.bak','before_sha256':sha(before),'after_sha256':sha(after),'before_bytes':len(before),'bytes':len(after),'decoded_pixel_ranges':ranges})
    (ROOT/'modding/smoke-neon-plan.json').write_text(json.dumps({'files':files,'installed':False,'gameplay_verified':False},indent=2)+'\n')
    print('Staged four files; every mip decoded transparent, unrelated bytes and chunk layout exact; game files untouched')


if __name__=='__main__':main()

"""Expand only active Corolla body bounds for the retargeted motion; stage, never install."""
import hashlib
import json
import struct
import numpy as np
from inspect_assets import ROOT,chunks,flatten
from extract_assets import geometry,payload

def prepare(source,minimum,maximum):
    result=bytearray(source);nodes={n['offset']:n for n in flatten(chunks(source))};changes=[]
    bodies=geometry(source,'_KIT00_BODY_')
    if {b['name'] for b in bodies}!={f'COROLLA_KIT00_BODY_{lod}' for lod in 'ABCD'}:raise ValueError('Unexpected body set')
    for mesh in bodies:
        leaves={n['id']:n for n in flatten(nodes[mesh['solid_offset']]['children'])}
        header=leaves['0x00134011'];ranges=leaves['0x00134b02'];raw=payload(source,ranges);lead=len(raw)%60
        active=[at for at in range(lead,len(raw),60) if struct.unpack_from('<I',raw,at+12)[0]]
        if len(active)!=1 or struct.unpack_from('<I',raw,active[0]+12)[0]!=len(mesh['indices']):raise ValueError('Unexpected active material range')
        for node,start in [(header,32),(ranges,active[0])]:
            for delta,values,operation in [(0,minimum,min),(16,maximum,max)]:
                for axis,value in enumerate(values):
                    at=node['payload']+start+delta+axis*4;old=struct.unpack_from('<f',source,at)[0];new=struct.pack('<f',operation(old,float(value)))
                    if source[at:at+4]!=new:result[at:at+4]=new;changes.append({'part':mesh['name'],'offset':at,'before':source[at:at+4].hex(),'after':new.hex()})
    if chunks(result)!=chunks(source):raise ValueError('Container layout changed')
    return bytes(result),changes

def main():
    report=json.loads((ROOT/'modding/animation-steam-retarget/retarget-report.json').read_text())
    target=ROOT/'CARS/COROLLA/GEOMETRY.BIN';backup=target.with_name('GEOMETRY.BIN.before-steam-motion.bak');source=(backup if backup.exists() else target).read_bytes()
    lower=np.array(report['minimum'])-.2;upper=np.array(report['maximum'])+.2;candidate,changes=prepare(source,lower,upper)
    (ROOT/'modding/staged-runtime/GEOMETRY-steam-motion.BIN').write_bytes(candidate)
    result={'before_sha256':hashlib.sha256(source).hexdigest(),'after_sha256':hashlib.sha256(candidate).hexdigest(),'bytes':len(candidate),'source_envelope_margin':.2,'minimum':lower.tolist(),'maximum':upper.tolist(),'fields':changes,'installed':False}
    (ROOT/'modding/steam-motion-bounds-plan.json').write_text(json.dumps(result,indent=2)+'\n');print('Staged body bounds:',len(changes),'four-byte fields;',result['after_sha256'])

if __name__=='__main__':main()

"""Make the independent front-end tire mask transparent; preserve decoded chunk layout."""
import hashlib
import json
import struct
from inspect_assets import ROOT,chunks,flatten,jdlz


def rewrite_jdlz(source,data):
    original=jdlz(source)
    if not data or len(data)!=len(original):raise ValueError('JDLZ decoded size changed')
    stream=bytearray();bit1=bit2=8;flag1=flag2=0
    def emit(literal,a,b=0,near=0):
        nonlocal bit1,bit2,flag1,flag2
        if bit1==8:flag1=len(stream);stream.append(0);bit1=0
        if bit2==8:flag2=len(stream);stream.append(0);bit2=0
        if literal:stream.append(a)
        else:
            stream[flag1]|=1<<bit1;stream[flag2]|=near<<bit2;bit2+=1;stream.extend((a,b))
        bit1+=1
    at=16;position=0;flags1=flags2=1
    while position<len(data):
        if flags1==1:flags1=source[at]|256;at+=1
        if flags2==1:flags2=source[at]|256;at+=1
        if flags1&1:
            a,b=source[at:at+2];at+=2;near=flags2&1
            length,distance=(((a&240)<<4|b)+3,(a&15)+1) if near else ((a&31)+3,(b|((a&224)<<3))+17)
            # A changed source pixel must never leak through a back-reference into another texture.
            if all(data[position+k]==data[position+k-distance] for k in range(length)):emit(False,a,b,near)
            else:
                for value in data[position:position+length]:emit(True,value)
            position+=length;flags2>>=1
        else:emit(True,data[position]);position+=1;at+=1
        flags1>>=1
    encoded=b'JDLZ\x02\x10\0\0'+struct.pack('<2I',len(data),len(stream)+16)+stream
    if jdlz(encoded)!=data:raise ValueError('JDLZ rewrite failed')
    return encoded


def prepare(source):
    original=jdlz(source);result=bytearray(original);matches=[]
    for tpk in flatten(chunks(original)):
        if tpk['id']!='0xb3300000':continue
        nodes=list(flatten(tpk['children']))
        infos=[n for n in nodes if n['id']=='0x33310004']
        pixels=[n for n in nodes if n['id']=='0x33320002']
        if len(infos)!=1 or len(pixels)!=1:continue
        info,data=infos[0],pixels[0]
        if info['size']%124:raise ValueError('Partial raw TextureInfo')
        for at in range(info['payload'],info['end'],124):
            if original[at+12:at+36].split(b'\0')[0]!=b'TIREMASK':continue
            key=struct.unpack_from('<I',original,at+36)[0]
            placement,size=struct.unpack_from('<I',original,at+48)[0],struct.unpack_from('<I',original,at+56)[0]
            width,height=struct.unpack_from('<HH',original,at+68)
            fmt,mips=original[at+74],original[at+78]
            if (key,width,height,fmt,mips,size)!=(0xc8cbb2df,128,128,0x22,5,10912):raise ValueError('Unexpected tire-mask format')
            begin=data['payload']+120+placement;end=begin+size
            if begin%128 or begin<data['payload']+120 or end>data['end']:raise ValueError('Mask pixels outside aligned TPK data')
            result[begin:end]=(b'\0\0\0\0\xff\xff\xff\xff')*(size//8)
            matches.append({'texture':'TIREMASK','texture_info_offset':at,'pixel_offset':begin,'pixel_bytes':size,'format':'DXT1','width':width,'height':height,'mips':mips})
    if len(matches)!=1:raise ValueError('Tire mask absent or ambiguous')
    if chunks(result)!=chunks(original):raise ValueError('Decoded chunk layout changed')
    encoded=rewrite_jdlz(source,result)
    if jdlz(encoded)!=result:raise ValueError('JDLZ round trip failed')
    return encoded,matches


def main():
    target=ROOT/'FRONTEND/FrontB.lzc';backup=target.with_name(target.name+'.before-uma-tiremask.bak')
    source=(backup if backup.exists() else target).read_bytes();candidate,ranges=prepare(source)
    out=ROOT/'modding/staged-runtime/FrontB.no-tiremask.lzc';out.write_bytes(candidate)
    plan={'target':str(target.relative_to(ROOT)),'backup':str(backup.relative_to(ROOT)),'candidate':str(out.relative_to(ROOT)),'before_bytes':len(source),'bytes':len(candidate),'before_sha256':hashlib.sha256(source).hexdigest(),'after_sha256':hashlib.sha256(candidate).hexdigest(),'decoded_pixel_ranges':ranges,'installed':False,'gameplay_verified':False}
    (ROOT/'modding/tiremask-plan.json').write_text(json.dumps(plan,indent=2)+'\n')
    print('Staged transparent front-end tire mask:',len(source),'->',len(candidate),'bytes; decoded offsets unchanged')


if __name__=='__main__':main()

"""Prove direct v0-to-clip matrix rows in captured VS1.1 programs; never read executables."""
import hashlib
import json
import struct
from inspect_assets import ROOT

LENGTHS={0:0,1:2,2:3,3:3,4:4,5:3,6:2,7:2,8:3,9:3,10:3,11:3,12:3,13:3,14:2,15:2,16:2,17:3,18:4,19:2,20:3,21:3,22:3,23:3,24:3,31:2,78:2,79:2,81:5}

def matrix_rows(words):
    if not words or words[0]!=0xfffe0101:raise ValueError('Only observed VS1.1 is supported')
    registers={};defined=set();at=1;ended=False
    def key(token):return ((token>>28)&7)|((token>>8)&24),token&2047
    def source(token):
        kind,index=key(token)
        if token&0x2000:return [None]*4
        values=registers.get((kind,index))
        if values is None:
            values=[('input',index,k) for k in range(4)] if kind==1 else [('constant',index,k,1) for k in range(4)] if kind==2 else [None]*4
        result=[values[(token>>(16+2*k))&3] for k in range(4)]
        modifier=(token>>24)&15
        if modifier==1:
            result=[v[:-1]+(-v[-1],) if v and v[0] in ('dot','constant') else None for v in result]
        elif modifier:result=[None]*4
        return result
    while at<len(words):
        instruction=words[at];at+=1;op=instruction&65535
        if op==65535:
            if instruction!=65535 or at!=len(words):raise ValueError('Invalid END')
            ended=True;break
        if op==65534:
            count=(instruction>>16)&32767
            if at+count>len(words):raise ValueError('Truncated comment')
            at+=count;continue
        if op not in LENGTHS or instruction!=op:raise ValueError('Unsupported instruction/flags')
        count=LENGTHS[op]
        if at+count>len(words):raise ValueError('Truncated operands')
        args=words[at:at+count];at+=count
        if not count or op==31:continue
        destination=args[0];kind,index=key(destination);mask=(destination>>16)&15;value=[None]*4
        if op==81:defined.add(index)
        elif op==1:value=source(args[1])
        elif op in (9,20):
            position=source(args[1]);constant=source(args[2])
            if position==[('input',0,k) for k in range(4)] and constant[0] is not None:
                register=constant[0][1];sign=constant[0][-1]
                if constant==[('constant',register,k,sign) for k in range(4)]:
                    value=[('dot',register+(k if op==20 else 0),sign) for k in range(4)]
        if destination&0x0ff00000:value=[None]*4
        prior=registers.get((kind,index),[None]*4).copy()
        for k in range(4):
            if mask&(1<<k):prior[k]=value[k]
        registers[(kind,index)]=prior
    if not ended:raise ValueError('Missing END')
    result=registers.get((4,0),[None]*4)
    if any(v is None or v[0]!='dot' or v[1] in defined for v in result):raise ValueError('Position is not a direct input matrix transform')
    return [(v[1],v[2]) for v in result]


def shader_metadata(words):
    table={};colored=False;at=1;uv_input=None;uv_output=-1
    while at<len(words):
        token=words[at];at+=1;op=token&65535
        if op==65535:break
        if op==65534:
            count=(token>>16)&32767
            if at+count>len(words):raise ValueError('Truncated metadata comment')
            comment=struct.pack(f'<{count}I',*words[at:at+count]);at+=count
            if comment[:4]!=b'CTAB':continue
            data=comment[4:]
            if len(data)<28:raise ValueError('Short CTAB')
            size,creator,version,number,info,flags,target=struct.unpack_from('<7I',data)
            if size!=28 or number>256 or info+number*20>len(data):raise ValueError('Invalid CTAB directory')
            for i in range(number):
                name,kind,register,n,res,typ,default=struct.unpack_from('<I4H2I',data,info+20*i)
                end=data.find(b'\0',name)
                if name>=len(data) or end<name or end-name>256:raise ValueError('Invalid constant name')
                if kind==2 and register+n<=256:table[data[name:end].decode('ascii')]=(register,n)
            continue
        if op not in LENGTHS or at+LENGTHS[op]>len(words):raise ValueError('Invalid metadata instruction')
        args=words[at:at+LENGTHS[op]];at+=LENGTHS[op]
        if op==31 and args[0]&0xf001f==10 and args[1]==0x900f0001:colored=True
        if op==31 and args[0]&0xf001f==5:uv_input=args[1]&2047
        if op==1 and uv_input is not None and args[1]==0x90e40000+uv_input and args[0]&0xf0001800==0xe0000000 and args[0]&0x30000==0x30000:uv_output=args[0]&2047
    worldview=table.get('WorldView')
    return (worldview[0] if worldview and worldview[1]==3 else -1),colored,uv_output


def main():
    path=ROOT/'modding/diagnostics/game-pipeline-session-1.log';raw=path.read_bytes();profiles=[];report=[]
    for line in raw.decode().splitlines():
        if not line.startswith('VS '):continue
        head,tokens=line.split('words=');words=[int(t,16) for t in tokens.split()];ident=int(head.split('id=')[1].split()[0]);data=struct.pack(f'<{len(words)}I',*words)
        entry={'id':ident,'sha256':hashlib.sha256(data).hexdigest(),'bytes':len(data)}
        try:
            rows=matrix_rows(words);wv,colored,uv=shader_metadata(words);profiles.append((ident,words,rows,wv,colored,uv));entry.update(rows=rows,worldview_register=wv,color_input_reference_candidate=colored,uv_output=uv)
        except ValueError as error:entry['unsupported_reason']=str(error)
        report.append(entry)
    lines=['/* Generated from explicitly captured GPU shader objects, not SPEED2.EXE. */','#ifndef UMA_SHADER_PROFILES_H','#define UMA_SHADER_PROFILES_H','typedef struct {const DWORD *words;UINT bytes;UINT rows[4];float signs[4];int worldview;BOOL reference_candidate;int uv_output;} UmaShaderProfile;']
    for ident,words,rows,wv,colored,uv in profiles:lines.append(f'static const DWORD uma_vs_{ident}[]={{'+','.join(hex(w) for w in words)+'};')
    lines.append('static const UmaShaderProfile uma_shader_profiles[]={')
    for ident,words,rows,wv,colored,uv in profiles:lines.append('{uma_vs_%d,sizeof(uma_vs_%d),{%s},{%s},%d,%d,%d},'%(ident,ident,','.join(str(r) for r,s in rows),','.join(str(s) for r,s in rows),wv,int(colored),uv))
    lines+=['};','#define UMA_SHADER_PROFILE_COUNT (sizeof(uma_shader_profiles)/sizeof(uma_shader_profiles[0]))','#endif','']
    (ROOT/'modding/runtime/uma_shader_profiles.h').write_text('\n'.join(lines))
    (ROOT/'modding/diagnostics/shader-profile-analysis.json').write_text(json.dumps({'source_sha256':hashlib.sha256(raw).hexdigest(),'programs':report,'exact_bytecode_match_required':True,'game_integration_verified':False},indent=2)+'\n')
    print('Proved direct position transforms:',[(i,r,wv,c) for i,w,r,wv,c,uv in profiles]);print('Rejected:',[r['id'] for r in report if 'unsupported_reason' in r])

if __name__=='__main__':main()

"""Bounded local CRI @UTF/AFS2 reader; source layout checked against UmaViewer."""
import struct

FORMATS=('B','b','H','h','I','i','Q','q','f','d','I','2I','16s')

def utf(data):
    if len(data)<32 or data[:4]!=b'@UTF':raise ValueError('Invalid UTF header')
    total,version,row_at,strings_at,blob_at,name_at,columns,width,rows=struct.unpack_from('>IHHIIIHHI',data,4)
    total+=8;row_at+=8;strings_at+=8;blob_at+=8
    if version not in (0,1) or total>len(data) or not 32<=row_at<=strings_at<blob_at<=total or columns>1024 or rows>100000 or row_at+rows*width>strings_at:raise ValueError('Invalid UTF table limits')
    def string(offset):
        at=strings_at+offset
        if at<strings_at or at>=blob_at:raise ValueError('Invalid UTF string offset')
        end=data.find(b'\0',at,blob_at)
        if end<0:raise ValueError('Unterminated UTF string')
        return data[at:end].decode('utf-8')
    def value(kind,at,limit):
        if kind>=len(FORMATS):raise ValueError('Unknown UTF value type')
        size=struct.calcsize('>'+FORMATS[kind])
        if at<0 or at+size>limit:raise ValueError('Truncated UTF value')
        values=struct.unpack_from('>'+FORMATS[kind],data,at)
        if kind==10:return string(values[0]),size
        if kind==11:
            offset,length=values
            if blob_at+offset>total or length>total-blob_at-offset:raise ValueError('UTF blob outside table')
            return data[blob_at+offset:blob_at+offset+length],size
        return values[0],size
    schema=[];at=32;row_offset=0
    for _ in range(columns):
        if at+5>row_at:raise ValueError('Truncated UTF schema')
        info,name=struct.unpack_from('>BI',data,at);at+=5;flags,kind=info&240,info&15
        if flags not in (16,48,80) or kind>=len(FORMATS):raise ValueError('Unsupported UTF column')
        size=struct.calcsize('>'+FORMATS[kind]);constant=None
        if flags==48:constant,used=value(kind,at,row_at);at+=used
        if flags==80:
            location=row_offset;row_offset+=size
        else:location=-1
        schema.append((string(name),kind,location,constant))
    if row_offset!=width:raise ValueError('UTF row width does not match schema')
    result=[]
    for row in range(rows):
        record={}
        for name,kind,offset,constant in schema:
            record[name]=value(kind,row_at+row*width+offset,row_at+(row+1)*width)[0] if offset>=0 else constant
        result.append(record)
    return string(name_at),result

def awb(data):
    if len(data)<16 or data[:4]!=b'AFS2':raise ValueError('Invalid AFS2 header')
    offset_width,id_width=data[5],struct.unpack_from('<H',data,6)[0]
    count,alignment,subkey=struct.unpack_from('<IHH',data,8)
    if offset_width not in (2,4) or id_width!=2 or not 0<alignment<=4096 or count>10000:raise ValueError('Unsupported AFS2 layout')
    table=16+count*id_width
    if table+(count+1)*offset_width>len(data):raise ValueError('Truncated AFS2 directory')
    seen=set()
    offsets=[int.from_bytes(data[table+i*offset_width:table+(i+1)*offset_width],'little') for i in range(count+1)];result=[]
    for i in range(count):
        begin=(offsets[i]+alignment-1)//alignment*alignment;end=offsets[i+1]
        if begin<table+(count+1)*offset_width or begin>end or end>len(data):raise ValueError('AFS2 member outside bank')
        ident=struct.unpack_from('<H',data,16+i*2)[0]
        if ident in seen:raise ValueError('Duplicate AFS2 wave ID')
        seen.add(ident);result.append((ident,data[begin:end]))
    return subkey,result
